def flatten(nested):
    """Flatten arbitrarily nested lists and tuples into a single list, keeping order.
    Strings are treated as atoms, not iterated."""
    result = []
    for item in nested:
        if isinstance(item, (list, tuple)):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result
