class LRUCache:
    """Least-recently-used cache with a fixed capacity.
    get(key) returns the value or -1 and marks the key as recently used.
    put(key, value) inserts/updates the key-value pair and marks the key as recently used.
    If the cache is at capacity, it evicts the least recently used item before inserting the new item."""

    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.order = []

    def get(self, key):
        if key in self.cache:
            self.order.remove(key)
            self.order.append(key)
            return self.cache[key]
        else:
            return -1

    def put(self, key, value):
        if key in self.cache:
            self.cache[key] = value
            self.order.remove(key)
            self.order.append(key)
        else:
            if len(self.cache) >= self.capacity:
                lru_key = self.order.pop(0)
                del self.cache[lru_key]
            self.cache[key] = value
            self.order.append(key)
