def fib(n):
    """Return the n-th Fibonacci number with fib(0) == 0 and fib(1) == 1."""
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b
